import { dynamicSamples } from '$shared/ipc';
import { dynamicOptions } from '$shared/settings';

// Dynamic variables in the editor (Flow · Dynamic variables): example values, generated by
// Rust with the current Settings → Variables, and the reference dialog (DV4).
class DynamicVars {
  /** `$name → example`. Empty until first needed. Replaced, never mutated in place. */
  samples = $state.raw<Record<string, string>>({});
  /** Whether the reference dialog is open. */
  catalogOpen = $state(false);
}
export const dynamicVars = new DynamicVars();

/** New examples with the current settings (a failed call, e.g. outside Tauri, keeps the old ones). */
export async function refreshDynamicSamples(): Promise<void> {
  try {
    dynamicVars.samples = await dynamicSamples(dynamicOptions());
  } catch {
    // Browser previews have no backend: the UI just shows no examples.
  }
}

let requested = false;
/** Example for `name`, loading the first batch on demand ('' until it arrives). */
export function dynamicSample(name: string): string {
  if (!requested) {
    requested = true;
    void refreshDynamicSamples();
  }
  return dynamicVars.samples[name] ?? '';
}

export const dynamicSamplesLoaded = (): boolean => Object.keys(dynamicVars.samples).length > 0;

export function openDynamicCatalog(): void {
  dynamicVars.catalogOpen = true;
}
